mapper.select:
SELECT COUNT(1) AS totalRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status = '成功' THEN 1 ELSE 0 END), 0) AS successRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status = '失败' THEN 1 ELSE 0 END), 0) AS failedRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status = '处理中' THEN 1 ELSE 0 END), 0) AS processingRequestCount, COALESCE(SUM(CASE WHEN filtered_requests.attempt_status = '等待回调' THEN 1 ELSE 0 END), 0) AS waitingCallbackRequestCount, COUNT(DISTINCT NULLIF(filtered_requests.terminal, '')) AS distinctTerminalCount, COUNT(DISTINCT NULLIF(filtered_requests.channel_code, '')) AS distinctChannelCount, COALESCE(( SELECT COUNT(1) FROM ( SELECT repeated_requests.payment_order_id FROM ( SELECT pa.payment_order_id, pa.response_payload, pa.attempt_status, pa.terminal, pa.channel_code, pa.client_ip, po.order_no, pa.attempt_no FROM t_payment_attempt pa LEFT JOIN t_payment_order po ON po.payment_order_id = pa.payment_order_id
) repeated_requests WHERE repeated_requests.payment_order_id IS NOT NULL GROUP BY repeated_requests.payment_order_id HAVING COUNT(1) > 1 ) repeated_payment_orders ), 0) AS repeatedPaymentOrderCount, COALESCE(SUM(CASE WHEN filtered_requests.response_payload IS NULL OR filtered_requests.response_payload = '' THEN 1 ELSE 0 END), 0) AS missingResponseCount, MAX(DATE_FORMAT(filtered_requests.created_at, '%Y-%m-%d %H:%i:%s')) AS latestRequestAt FROM ( SELECT pa.payment_order_id, pa.response_payload, pa.attempt_status, pa.terminal, pa.channel_code, pa.client_ip, pa.created_at, po.order_no, pa.attempt_no FROM t_payment_attempt pa LEFT JOIN t_payment_order po ON po.payment_order_id = pa.payment_order_id
) filtered_requests
